CREATE TRIGGER v1_product_source_update AFTER UPDATE OF enabled,input,source_url,username,kind,provider,actor_input_json ON sources WHEN NEW.enabled!=OLD.enabled OR NEW.input IS NOT OLD.input OR NEW.source_url IS NOT OLD.source_url OR NEW.username IS NOT OLD.username OR NEW.kind!=OLD.kind OR NEW.provider!=OLD.provider OR NEW.actor_input_json IS NOT OLD.actor_input_json BEGIN  UPDATE v1_intake_scopes SET json=json_set(json,'$.enabled',json('false')),epoch=epoch+1 WHERE id=NEW.id AND json_extract(json,'$.deletedAt') IS NULL;  UPDATE v1_feeds SET json=json_set(json,'$.revision',json_extract(json,'$.revision')+1,'$.updatedAt',strftime('%Y-%m-%dT%H:%M:%fZ','now')),epoch=epoch+1 WHERE id=NEW.briefing_id AND json_extract(json,'$.deletedAt') IS NULL; END;
CREATE TRIGGER v1_product_source_delete BEFORE DELETE ON sources BEGIN  UPDATE v1_intake_scopes SET json=json_set(json,'$.enabled',json('false'),'$.deletedAt',strftime('%Y-%m-%dT%H:%M:%fZ','now')),epoch=epoch+1 WHERE id=OLD.id AND json_extract(json,'$.deletedAt') IS NULL;  UPDATE v1_feeds SET json=json_set(json,'$.revision',json_extract(json,'$.revision')+1,'$.updatedAt',strftime('%Y-%m-%dT%H:%M:%fZ','now')),epoch=epoch+1 WHERE id=OLD.briefing_id AND json_extract(json,'$.deletedAt') IS NULL; END;
CREATE TRIGGER v1_product_feed_update AFTER UPDATE OF title,interest_profile,language,paused,briefing_cadence,briefing_time_of_day,briefing_timezone ON briefings WHEN NEW.title!=OLD.title OR NEW.interest_profile!=OLD.interest_profile OR NEW.language!=OLD.language OR NEW.paused!=OLD.paused OR NEW.briefing_cadence!=OLD.briefing_cadence OR NEW.briefing_time_of_day IS NOT OLD.briefing_time_of_day OR NEW.briefing_timezone IS NOT OLD.briefing_timezone BEGIN  UPDATE v1_feeds SET json=json_set(json,'$.paused',json('true'),'$.revision',json_extract(json,'$.revision')+1,'$.updatedAt',strftime('%Y-%m-%dT%H:%M:%fZ','now')),epoch=epoch+1 WHERE id=NEW.id AND json_extract(json,'$.deletedAt') IS NULL;  UPDATE v1_intake_scopes SET json=json_set(json,'$.enabled',json('false')),epoch=epoch+1 WHERE feed_id=NEW.id AND json_extract(json,'$.deletedAt') IS NULL; END;
CREATE TRIGGER v1_product_feed_delete BEFORE DELETE ON briefings BEGIN  UPDATE v1_feeds SET json=json_set(json,'$.paused',json('true'),'$.deletedAt',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'$.revision',json_extract(json,'$.revision')+1,'$.updatedAt',strftime('%Y-%m-%dT%H:%M:%fZ','now')),epoch=epoch+1 WHERE id=OLD.id AND json_extract(json,'$.deletedAt') IS NULL;  UPDATE v1_intake_scopes SET json=json_set(json,'$.enabled',json('false'),'$.deletedAt',strftime('%Y-%m-%dT%H:%M:%fZ','now')),epoch=epoch+1 WHERE feed_id=OLD.id AND json_extract(json,'$.deletedAt') IS NULL; END;
CREATE TRIGGER v1_product_account_disabled AFTER UPDATE OF disabled_at ON accounts WHEN NEW.disabled_at IS NOT NULL AND OLD.disabled_at IS NULL BEGIN  UPDATE v1_feeds SET json=json_set(json,'$.paused',json('true'),'$.revision',json_extract(json,'$.revision')+1,'$.updatedAt',strftime('%Y-%m-%dT%H:%M:%fZ','now')),epoch=epoch+1 WHERE json_extract(json,'$.ownerId')=NEW.id AND json_extract(json,'$.deletedAt') IS NULL;  UPDATE v1_intake_scopes SET json=json_set(json,'$.enabled',json('false')),epoch=epoch+1 WHERE feed_id IN (SELECT id FROM briefings WHERE owner_account_id=NEW.id) AND json_extract(json,'$.deletedAt') IS NULL; END;
CREATE TRIGGER v1_product_source_insert AFTER INSERT ON sources BEGIN UPDATE v1_feeds SET json=json_set(json,'$.paused',json('true'),'$.revision',json_extract(json,'$.revision')+1,'$.updatedAt',strftime('%Y-%m-%dT%H:%M:%fZ','now')),epoch=epoch+1 WHERE id=NEW.briefing_id AND json_extract(json,'$.deletedAt') IS NULL; UPDATE v1_intake_scopes SET json=json_set(json,'$.enabled',json('false')),epoch=epoch+1 WHERE feed_id=NEW.briefing_id AND json_extract(json,'$.deletedAt') IS NULL; END;
